package com.rizenic.backend.parts;
import com.rizenic.backend.parts.PartsDtos.*;
import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.stereotype.Repository; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;

@Repository
public class PartsRepository {
 private final JdbcClient db; public PartsRepository(JdbcClient db){this.db=db;}
 private Long branch(String name){return db.sql("select id from rizenic_new.branches where lower(name)=lower(:n) and is_active=true").param("n",name).query(Long.class).optional().orElseThrow(()->new IllegalArgumentException("ไม่พบสาขา: "+name));}
 private Long part(String no){return db.sql("select id from rizenic_new.parts where part_number=:p and is_active=true").param("p",no).query(Long.class).optional().orElseThrow(()->new IllegalArgumentException("ไม่พบอะไหล่: "+no));}
 private Object dateValue(Object value){if(value==null||value.toString().isBlank()) return null; if(value instanceof LocalDate) return value; return LocalDate.parse(value.toString());}
 public List<Part> findParts(){return db.sql("select p.id,p.id part_id,p.part_number,p.main_part_number,p.name,p.category,p.unit,p.default_unit_price,p.is_active,p.compatible_with_all_models,coalesce(string_agg(distinct cm.model_name, ', '),'ALL') car_model,coalesce(string_agg(distinct bp.storage_location, ', '),'') location,coalesce(max(bp.safety_stock),0) safety_stock from rizenic_new.parts p left join rizenic_new.branch_parts bp on bp.part_id=p.id left join rizenic_new.part_compatible_models pcm on pcm.part_id=p.id left join rizenic_new.car_models cm on cm.id=pcm.car_model_id where p.is_active=true group by p.id order by p.name").query((r,n)->new Part(r.getLong("id"),r.getLong("part_id"),r.getString("part_number"),r.getString("main_part_number"),r.getString("name"),r.getString("category"),r.getString("unit"),r.getBigDecimal("default_unit_price"),r.getString("location"),r.getBigDecimal("safety_stock"),r.getString("car_model"),r.getBoolean("is_active"),r.getBoolean("compatible_with_all_models"))).list();}
 public Optional<Part> check(String no){return db.sql("select p.id,p.id part_id,p.part_number,p.main_part_number,p.name,p.category,p.unit,p.default_unit_price,p.is_active,p.compatible_with_all_models,coalesce(string_agg(distinct cm.model_name, ', '),'ALL') car_model,coalesce(string_agg(distinct bp.storage_location, ', '),'') location,coalesce(max(bp.safety_stock),0) safety_stock from rizenic_new.parts p left join rizenic_new.branch_parts bp on bp.part_id=p.id left join rizenic_new.part_compatible_models pcm on pcm.part_id=p.id left join rizenic_new.car_models cm on cm.id=pcm.car_model_id where p.part_number=:p group by p.id").param("p",no).query((r,n)->new Part(r.getLong("id"),r.getLong("part_id"),r.getString("part_number"),r.getString("main_part_number"),r.getString("name"),r.getString("category"),r.getString("unit"),r.getBigDecimal("default_unit_price"),r.getString("location"),r.getBigDecimal("safety_stock"),r.getString("car_model"),r.getBoolean("is_active"),r.getBoolean("compatible_with_all_models"))).optional();}
 public Part savePart(Long id,PartRequest x){ if(x.partNo()==null||x.name()==null)throw new IllegalArgumentException("part_no และ part_name จำเป็น"); if(id==null){ db.sql("insert into rizenic_new.parts(part_number,main_part_number,name,category,unit,default_unit_price,compatible_with_all_models) values(:no,:main,:name,:cat,coalesce(:unit,'piece'),:price,coalesce(:all,false))").param("no",x.partNo()).param("main",x.mainPartNo()).param("name",x.name()).param("cat",x.category()).param("unit",x.unit()).param("price",x.defaultPrice()).param("all",x.compatibleAll()).update(); return check(x.partNo()).orElseThrow(); } db.sql("update rizenic_new.parts set part_number=:no,main_part_number=:main,name=:name,category=:cat,unit=coalesce(:unit,unit),default_unit_price=coalesce(:price,default_unit_price),compatible_with_all_models=coalesce(:all,compatible_with_all_models),is_active=true where id=:id").param("id",id).param("no",x.partNo()).param("main",x.mainPartNo()).param("name",x.name()).param("cat",x.category()).param("unit",x.unit()).param("price",x.defaultPrice()).param("all",x.compatibleAll()).update(); return check(x.partNo()).orElseThrow(); }
 public void deletePart(Long id){db.sql("update rizenic_new.parts set is_active=false where id=:id").param("id",id).update();}
 public List<PartStatus> statuses(){return db.sql("select id,code,name,is_active from rizenic_new.part_order_statuses where is_active=true order by id").query((r,n)->new PartStatus(r.getLong("id"),r.getString("code"),r.getString("name"),r.getBoolean("is_active"))).list();}
 public PartStatus saveStatus(StatusRequest x){return db.sql("insert into rizenic_new.part_order_statuses(code,name) values(:c,:n) returning id,code,name,is_active").param("c",x.code()==null?x.name():x.code()).param("n",x.name()).query((r,n)->new PartStatus(r.getLong("id"),r.getString("code"),r.getString("name"),r.getBoolean("is_active"))).single();}
 public void deleteStatus(Long id){db.sql("update rizenic_new.part_order_statuses set is_active=false where id=:id").param("id",id).update();}
 public Long createOrder(OrderRequest x){var b=branch(x.branchName()); var oid=db.sql("insert into rizenic_new.part_orders(branch_id,epc_reference,ordered_on,notes) values(:b,:e,:d,:n) returning id").param("b",b).param("e",x.epcNo()).param("d",x.orderDate()).param("n",x.notes()).query(Long.class).single(); var lines=x.items()!=null&&x.items().length>0?x.items():new ListItemRequest[]{new ListItemRequest(x.partNo(),x.partName(),x.quantity(),x.jobId(),x.status(),null)}; int line=1; for(var i:lines){var p=part(i.partNo()); db.sql("insert into rizenic_new.part_order_items(branch_id,order_id,line_number,job_id,part_id,status_id,description,part_type,quantity_ordered) values(:b,:o,:l,:j,:p,(select id from rizenic_new.part_order_statuses where code=:s or name=:s limit 1),:d,:t,:q)").param("b",b).param("o",oid).param("l",line++).param("j",i.jobId()).param("p",p).param("s",i.status()==null?"":i.status()).param("d",i.partName()==null?i.partNo():i.partName()).param("t",i.partType()).param("q",i.quantity()==null?BigDecimal.ONE:i.quantity()).update();} return oid;}
 public List<LinkedHashMap<String,Object>> orders(){return db.sql("select o.id order_id,b.name branch_name,o.epc_reference epc_no,o.ordered_on order_date,o.notes,oi.id item_id,p.part_number part_no,p.main_part_number part_main_no,oi.description part_name,oi.quantity_ordered qty_ordered,coalesce(rt.quantity_received,0) qty_received,oi.job_id,coalesce(s.name,'') order_status,oi.estimated_arrival_on est_arrival_date,oi.reported_received_on received_date,v.plate_number car_plate,v.vin vin_no,cm.model_name car_model,max(case when d.document_type='QT' then d.document_number end) qt_no,max(case when d.document_type='SO' then d.document_number end) so_no from rizenic_new.part_orders o join rizenic_new.branches b on b.id=o.branch_id left join rizenic_new.part_order_items oi on oi.order_id=o.id left join rizenic_new.parts p on p.id=oi.part_id left join rizenic_new.part_order_statuses s on s.id=oi.status_id left join rizenic_new.part_order_receipt_totals rt on rt.order_item_id=oi.id left join rizenic_new.repair_jobs j on j.id=oi.job_id left join rizenic_new.vehicles v on v.id=j.vehicle_id left join rizenic_new.car_models cm on cm.id=v.car_model_id left join rizenic_new.job_documents d on d.job_id=j.id group by o.id,b.name,o.epc_reference,o.ordered_on,o.notes,oi.id,p.part_number,p.main_part_number,oi.description,oi.quantity_ordered,rt.quantity_received,oi.job_id,s.name,oi.estimated_arrival_on,oi.reported_received_on,v.plate_number,v.vin,cm.model_name order by o.id desc,oi.line_number").query((r,n)->{var m=new LinkedHashMap<String,Object>(); for(var k:List.of("order_id","branch_name","epc_no","order_date","notes","item_id","part_no","part_main_no","part_name","qty_ordered","qty_received","job_id","order_status","est_arrival_date","received_date","car_plate","car_model","vin_no","qt_no","so_no"))m.put(k,r.getObject(k));return m;}).list();}
 public void fastOrder(Long id,String field,Object value){String col=switch(field){case "epc_no"->"epc_reference";case "order_date"->"ordered_on";case "notes"->"notes";default->null;}; if(col!=null){db.sql("update rizenic_new.part_orders set "+col+"=:v where id=:id").param("v",field.endsWith("date")?dateValue(value):value).param("id",id).update();return;} if("car_plate".equals(field)){db.sql("update rizenic_new.vehicles set plate_number=:v where id=(select j.vehicle_id from rizenic_new.part_order_items oi join rizenic_new.repair_jobs j on j.id=oi.job_id where oi.order_id=:id limit 1)").param("v",value).param("id",id).update();return;} String item=switch(field){case "part_name"->"description";case "qty_ordered"->"quantity_ordered";case "job_id"->"job_id";case "received_date","part_received_all_date"->"reported_received_on";case "est_arrival_date"->"estimated_arrival_on";default->null;}; if("order_status".equals(field)){db.sql("update rizenic_new.part_order_items set status_id=(select id from rizenic_new.part_order_statuses where name=:v or code=:v limit 1) where id=(select id from rizenic_new.part_order_items where order_id=:id order by line_number limit 1)").param("v",value).param("id",id).update();return;} if("part_no".equals(field)){db.sql("update rizenic_new.part_order_items set part_id=(select id from rizenic_new.parts where part_number=:v) where id=(select id from rizenic_new.part_order_items where order_id=:id order by line_number limit 1)").param("v",value).param("id",id).update();return;} if(item==null)throw new IllegalArgumentException("ไม่อนุญาตให้แก้ฟิลด์นี้"); db.sql("update rizenic_new.part_order_items set "+item+"=:v where id=(select id from rizenic_new.part_order_items where order_id=:id order by line_number limit 1)").param("v",item.contains("_on")?dateValue(value):value).param("id",id).update();}
 public void deleteOrder(Long id){db.sql("delete from rizenic_new.part_order_items where order_id=:id and not exists(select 1 from rizenic_new.part_receipt_items ri where ri.order_item_id=part_order_items.id)").param("id",id).update();db.sql("delete from rizenic_new.part_orders where id=:id and not exists(select 1 from rizenic_new.part_order_items where order_id=:id)").param("id",id).update();}
 public Long createReceipt(ReceiptRequest x){var b=branch(x.branchName()); var p=part(x.partNo()); var rid=db.sql("insert into rizenic_new.part_receipts(branch_id,epc_reference,received_on) values(:b,:e,:d) returning id").param("b",b).param("e",x.epcNo()).param("d",x.receivedDate()).query(Long.class).single(); var qty=x.qty()==null?BigDecimal.ONE:x.qty(); var orderItem=db.sql("select oi.id from rizenic_new.part_order_items oi join rizenic_new.part_orders o on o.id=oi.order_id where oi.part_id=:p and (:e is null or o.epc_reference=:e) order by oi.id desc limit 1").param("p",p).param("e",x.epcNo()).query(Long.class).optional().orElse(null); var iid=db.sql("insert into rizenic_new.part_receipt_items(branch_id,receipt_id,line_number,order_item_id,part_id,description,quantity,unit_price) values(:b,:r,1,:oi,:p,:d,:q,:u) returning id").param("b",b).param("r",rid).param("oi",orderItem).param("p",p).param("d",x.partName()).param("q",qty).param("u",x.unitPrice()).query(Long.class).single(); if(orderItem!=null) db.sql("update rizenic_new.part_order_items oi set reported_received_on=:d,status_id=(select id from rizenic_new.part_order_statuses where name=case when (select quantity_received from rizenic_new.part_order_receipt_totals where order_item_id=oi.id)>=oi.quantity_ordered then 'อะไหล่มาครบแล้ว' else 'อะไหล่ยังมาไม่ครบ' end limit 1) where oi.id=:oi").param("d",x.receivedDate()).param("oi",orderItem).update(); db.sql("insert into rizenic_new.stock_movements(branch_id,part_id,movement_type,quantity_delta,unit_price,movement_on,receipt_item_id,reason) values(:b,:p,'RECEIPT',:q,:u,:d,:i,'API inbound')").param("b",b).param("p",p).param("q",qty).param("u",x.unitPrice()).param("d",x.receivedDate()).param("i",iid).update(); return rid;}
 public List<LinkedHashMap<String,Object>> receipts(){return db.sql("select r.id inbound_id,b.name branch_name,r.received_on received_date,r.epc_reference epc_no,ri.id item_id,p.part_number part_no,p.main_part_number part_main_no,ri.description part_name,ri.quantity qty,ri.unit_price,cm.model_name car_model from rizenic_new.part_receipts r join rizenic_new.branches b on b.id=r.branch_id join rizenic_new.part_receipt_items ri on ri.receipt_id=r.id join rizenic_new.parts p on p.id=ri.part_id left join rizenic_new.part_order_items oi on oi.id=ri.order_item_id left join rizenic_new.repair_jobs j on j.id=oi.job_id left join rizenic_new.vehicles v on v.id=j.vehicle_id left join rizenic_new.car_models cm on cm.id=v.car_model_id order by r.id desc").query((r,n)->{var m=new LinkedHashMap<String,Object>(); for(var k:List.of("inbound_id","branch_name","received_date","epc_no","item_id","part_no","part_main_no","part_name","qty","unit_price","car_model"))m.put(k,r.getObject(k));return m;}).list();}
 public void fastReceipt(Long id,String field,Object value){String col=switch(field){case "received_date"->"received_on";case "epc_no"->"epc_reference";default->null;}; if(col!=null){db.sql("update rizenic_new.part_receipts set "+col+"=:v where id=:id").param("v",field.equals("received_date")?dateValue(value):value).param("id",id).update();return;} String item=switch(field){case "qty"->"quantity";case "unit_price"->"unit_price";case "part_name"->"description";default->null;};if(item==null)throw new IllegalArgumentException("ไม่อนุญาตให้แก้ฟิลด์นี้");db.sql("update rizenic_new.part_receipt_items set "+item+"=:v where receipt_id=:id").param("v",value).param("id",id).update();}
 public Long createOutbound(OutboundRequest x){var b=branch(x.branchName());var p=part(x.partNo());var qty=x.qty()==null?BigDecimal.ONE:x.qty();var available=db.sql("select quantity_available from rizenic_new.inventory_balances where branch_id=:b and part_id=:p").param("b",b).param("p",p).query(BigDecimal.class).optional().orElse(BigDecimal.ZERO); if(available.compareTo(qty)<0) throw new IllegalArgumentException("สต็อกไม่พอ: available="+available); var on=x.issueDate()==null?LocalDate.now():x.issueDate();var onId=db.sql("insert into rizenic_new.stock_movements(branch_id,part_id,movement_type,quantity_delta,unit_price,movement_on,job_id,reason) values(:b,:p,'ISSUE',(:q * -1),:u,:d,:j,'API outbound') returning id").param("b",b).param("p",p).param("q",qty).param("u",x.unitPrice()).param("d",on).param("j",x.jobId()).query(Long.class).single();return onId;}
 public List<Outbound> outbounds(){return db.sql("select m.id outbound_id,b.name branch_name,m.movement_on issue_date,p.part_number part_no,p.main_part_number part_main_no,p.name part_name,(-m.quantity_delta) qty,coalesce(js.name,'') job_status,v.plate_number car_plate,max(case when d.document_type='QT' then d.document_number end) qt_no,max(case when d.document_type='SO' then d.document_number end) so_no from rizenic_new.stock_movements m join rizenic_new.branches b on b.id=m.branch_id join rizenic_new.parts p on p.id=m.part_id left join rizenic_new.repair_jobs j on j.id=m.job_id left join rizenic_new.job_statuses js on js.id=j.status_id left join rizenic_new.vehicles v on v.id=j.vehicle_id left join rizenic_new.job_documents d on d.job_id=j.id where m.movement_type='ISSUE' group by m.id,b.name,m.movement_on,p.part_number,p.main_part_number,p.name,m.quantity_delta,js.name,v.plate_number order by m.id desc").query((r,n)->new Outbound(r.getLong("outbound_id"),r.getLong("outbound_id"),r.getString("branch_name"),r.getObject("issue_date",LocalDate.class),r.getString("part_no"),r.getString("part_main_no"),r.getString("part_name"),r.getBigDecimal("qty"),r.getString("job_status"),r.getString("car_plate"),r.getString("qt_no"),r.getString("so_no"))).list();}
 public void fastOutbound(Long id,String field,Object value){String col=switch(field){case "issue_date"->"movement_on";default->null;};if(col==null)throw new IllegalArgumentException("ไม่อนุญาตให้แก้ฟิลด์นี้");db.sql("update rizenic_new.stock_movements set "+col+"=:v where id=:id and movement_type='ISSUE'").param("v",dateValue(value)).param("id",id).update();}
 public void reverseOutbound(Long id){db.sql("insert into rizenic_new.stock_movements(branch_id,part_id,movement_type,quantity_delta,movement_on,reason) select branch_id,part_id,'RETURN',-quantity_delta,current_date,'API outbound reversal' from rizenic_new.stock_movements where id=:id and movement_type='ISSUE'").param("id",id).update();}
 public List<Inventory> inventory(String branchName){var b=branch(branchName);return db.sql("select p.main_part_number part_main_no,p.part_number part_no,p.name part_name,(case when p.compatible_with_all_models then 'ALL' else coalesce((select string_agg(cm.model_name, ', ') from rizenic_new.part_compatible_models pcm join rizenic_new.car_models cm on cm.id=pcm.car_model_id where pcm.part_id=p.id),'') end) car_model,coalesce(i.quantity_on_hand,0) quantity_on_hand,coalesce(i.quantity_reserved,0) quantity_reserved,coalesce(i.quantity_available,0) quantity_available,coalesce((select sum(sm.quantity_delta) from rizenic_new.stock_movements sm where sm.branch_id=i.branch_id and sm.part_id=i.part_id and sm.quantity_delta>0),0) total_inbound,coalesce((select sum(-sm.quantity_delta) from rizenic_new.stock_movements sm where sm.branch_id=i.branch_id and sm.part_id=i.part_id and sm.movement_type='ISSUE'),0) total_issued,coalesce(i.quantity_reserved,0) total_booked from rizenic_new.inventory_balances i join rizenic_new.parts p on p.id=i.part_id where i.branch_id=:b order by p.name").param("b",b).query((r,n)->new Inventory(r.getString("part_main_no"),r.getString("part_no"),r.getString("part_name"),r.getString("car_model"),r.getBigDecimal("total_inbound"),r.getBigDecimal("total_issued"),r.getBigDecimal("total_booked"),r.getBigDecimal("quantity_on_hand"),r.getBigDecimal("quantity_reserved"),r.getBigDecimal("quantity_available"))).list();}
}
